WITH customer_refunds AS ( SELECT cr.cr_refunded_customer_sk AS customer_sk, SUM(cr.cr_refunded_cash) AS total_refunded_cash, SUM(cr.cr_net_loss) AS total_refund_loss, MAX(cr.cr_returned_time_sk) AS last_return_time_sk FROM catalog_returns cr GROUP BY cr.cr_refunded_customer_sk ), customer_sales AS ( SELECT ss.ss_customer_sk AS customer_sk, SUM(ss.ss_net_paid) AS total_sales, COUNT(*) AS purchase_count, AVG(ss.ss_ext_discount_amt) AS avg_discount, SUM(ss.ss_ext_tax) AS total_tax FROM store_sales ss GROUP BY ss.ss_customer_sk ), ranked_customers AS ( SELECT cr.customer_sk, cr.total_refunded_cash, cr.total_refund_loss, cr.last_return_time_sk, ROW_NUMBER() OVER (ORDER BY cr.total_refunded_cash DESC) AS rn FROM customer_refunds cr ) SELECT rc.customer_sk, rc.total_refunded_cash, rc.total_refund_loss, cs.total_sales, cs.purchase_count, cs.avg_discount, CASE WHEN cs.total_sales IS NULL THEN 'No Sales' ELSE 'Has Sales' END AS sales_status, t.t_hour AS last_return_hour, RANK() OVER (ORDER BY rc.total_refunded_cash DESC) AS refund_rank FROM ranked_customers rc LEFT JOIN customer_sales cs ON rc.customer_sk = cs.customer_sk LEFT JOIN time_dim t ON rc.last_return_time_sk = t.t_time_sk WHERE rc.rn <= 10 ORDER BY rc.total_refunded_cash DESC
